"""
Bundle UI assets into a C++ header for 100% standalone single-binary execution.
"""
import os

UI_DIR = os.path.join(os.path.dirname(__file__), "..", "src", "ui")
OUT_HEADER = os.path.join(UI_DIR, "embedded_assets.h")

FILES = [
    ("index.html", "INDEX_HTML", False),
    ("styles.css", "STYLES_CSS", False),
    ("app.js", "APP_JS", False),
    ("treemap_renderer.js", "TREEMAP_RENDERER_JS", False),
    ("logo.svg", "LOGO_SVG", False),
    ("favicon.ico", "FAVICON_ICO", True),
]

lines = [
    "// Auto-generated by scripts/bundle_assets.py - DO NOT EDIT MANUALLY",
    "#pragma once",
    "#include <string>",
    "#include <string_view>",
    "",
    "namespace TreeMCP::EmbeddedAssets {",
    ""
]

for filename, var_name, is_binary in FILES:
    filepath = os.path.join(UI_DIR, filename)
    if not os.path.exists(filepath):
        print(f"Warning: {filepath} missing!")
        continue
    
    with open(filepath, "rb") as f:
        data = f.read()

    # Emit as const unsigned char array
    byte_strs = [f"0x{b:02x}" for b in data]
    # Group in lines of 16
    lines.append(f"// Embedded asset: {filename} ({len(data)} bytes)")
    lines.append(f"static const unsigned char ASSET_{var_name}[] = {{")
    for i in range(0, len(byte_strs), 16):
        chunk = ", ".join(byte_strs[i:i+16])
        comma = "," if i + 16 < len(byte_strs) else ""
        lines.append(f"    {chunk}{comma}")
    lines.append("};")
    lines.append(f"static const size_t ASSET_{var_name}_LEN = {len(data)};")
    lines.append("")

lines.extend([
    "inline std::string get_asset(std::string_view name) {",
    "    if (name == \"index.html\") {",
    "        return std::string(reinterpret_cast<const char*>(ASSET_INDEX_HTML), ASSET_INDEX_HTML_LEN);",
    "    } else if (name == \"styles.css\") {",
    "        return std::string(reinterpret_cast<const char*>(ASSET_STYLES_CSS), ASSET_STYLES_CSS_LEN);",
    "    } else if (name == \"app.js\") {",
    "        return std::string(reinterpret_cast<const char*>(ASSET_APP_JS), ASSET_APP_JS_LEN);",
    "    } else if (name == \"treemap_renderer.js\") {",
    "        return std::string(reinterpret_cast<const char*>(ASSET_TREEMAP_RENDERER_JS), ASSET_TREEMAP_RENDERER_JS_LEN);",
    "    } else if (name == \"logo.svg\") {",
    "        return std::string(reinterpret_cast<const char*>(ASSET_LOGO_SVG), ASSET_LOGO_SVG_LEN);",
    "    } else if (name == \"favicon.ico\") {",
    "        return std::string(reinterpret_cast<const char*>(ASSET_FAVICON_ICO), ASSET_FAVICON_ICO_LEN);",
    "    }",
    "    return \"\";",
    "}",
    "} // namespace TreeMCP::EmbeddedAssets",
    ""
])

with open(OUT_HEADER, "w", encoding="utf-8") as f:
    f.write("\n".join(lines))

print(f"Generated {OUT_HEADER}")
